import React, { useContext, useEffect, useState } from "react";
import Cookies from "js-cookie";
import { Input, Button, Form, App, Space, Typography } from "antd";
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation, Link } from "react-router-dom";
import { Regex, ActionType, API, Enum } from "../../../resources/constants";
import language from "../../../resources/languages/en_US";

// Interfaces
import { AxiosError } from "../../../interfaces/axios"

// Contexts
import GlobalContext from "../../../contexts/global";
import AxiosContext from "../../../contexts/axios";

const { Pages: { SignIn: SignInLanguage, SignUp: SignUpLanguage }, Validation, Share, Message: MessageLanguage } = language
const { isEmail } = Regex
const { SET_USER, SET_ACCESS_TOKEN } = ActionType
const { USER_MANAGEMENT_AUTH_SIGN_IN, USER_MANAGEMENT_PROFILE_MY_ACCOUNT, USER_MANAGEMENT_AUTH_SIGN_IN_GOOGLE, USER_MANAGEMENT_AUTH_SIGN_IN_LINKEDIN } = API
const { Message } = Enum

export default function SignIn() {

    const [form] = Form.useForm()
    const [, forceUpdate] = useState({})
    const { meta, baseURL, dispatch } = useContext(GlobalContext)
    const { axios } = useContext(AxiosContext)
    const navigate = useNavigate()
    const location = useLocation()
    const { message } = App.useApp()

    useEffect(() => {
        // To disable submit button at the beginning.
        forceUpdate({});
    }, []);

    const onFinish = ({ email, password }: { email: string, password: string }) => {
        axios.post(USER_MANAGEMENT_AUTH_SIGN_IN, { email, password }).then((response: { data: { accessToken: string }}) => {
            const { data: { accessToken } } = response
            Cookies.set('accessToken', accessToken, { expires: 365 })
            dispatch({ type: SET_ACCESS_TOKEN , payload: { accessToken }})
            axios.get(USER_MANAGEMENT_PROFILE_MY_ACCOUNT).then((response: { data: {} }) => {
                const { data: user } = response
                dispatch({ type: SET_USER , payload: { user }})
                navigate(location.state?.from?.pathname || "/", { replace: true });
                message.success(MessageLanguage[Message.SIGN_IN_PROFILE]).then(response => response)
            })
        }, async (error: AxiosError) => {
            const { response: { data } } = error;
            // @ts-ignore
            message.error(MessageLanguage[data.message]).then(response => response )
        })
    };

    return (
        <>
          { meta?.title && (
            <Helmet>
              <title>{ SignInLanguage.signIn + ' - ' + meta.title }</title>
            </Helmet>
          )
          }
          <Form form={form} name="sign-in" className={'sign-in w-full max-w-md bg-white rounded-3xl shadow-2xl p-10'} autoComplete="off" onFinish={onFinish}>
              <Space direction="vertical" size="middle" style={{width: '100%'}}>
                  <div className="flex justify-center">
                      <img alt={SignInLanguage.signIn} src={require('../../../resources/media/logo.png')} width={70}/>
                  </div>
                  <Typography.Title
                      className="text-center"
                      level={2}
                  >{SignInLanguage.title}</Typography.Title>
                  <Form.Item
                      label={SignInLanguage.email}
                      className="mb-2"
                      name="email"
                      hasFeedback
                      rules={[
                          {required: true, message: `${SignInLanguage.email} ${Validation.required}`},
                          {pattern: isEmail, message: Validation.email},
                      ]}
                  >
                      <Input
                          className="peer w-full h-12 rounded-full bg-white border border-gray-300 px-5 text-sm placeholder-transparent focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent transition"
                          placeholder={SignInLanguage.emailPlaceholder}
                      />
                  </Form.Item>
                  <Form.Item
                      label={SignInLanguage.password}
                      className="mb-2"
                      name="password"
                      hasFeedback
                      rules={[
                          {required: true, message: `${SignInLanguage.password} ${Validation.required}`},
                      ]}
                  >
                      <Input.Password
                          className="w-full h-12 rounded-full border border-gray-300 px-5 text-sm focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent transition"
                          placeholder={SignInLanguage.passwordPlaceholder}
                      />
                  </Form.Item>
                  <Form.Item className="mb-2" shouldUpdate>
                      {() => (
                          <Button
                              type="primary"
                              block
                              htmlType="submit"
                              className="w-full h-12 rounded-full bg-gradient-to-r from-gray-800 to-black text-white font-medium hover:opacity-90 transition duration-200"
                          >
                              {SignInLanguage.signIn}
                          </Button>
                      )}
                  </Form.Item>
                  <Typography.Text className="flex justify-center">{Share.or}</Typography.Text>
                  <Button
                      icon={<img src={require('../../../resources/media/social/google.png')} width={24}/>}
                      block
                      // onClick={() => window.location.replace(`${baseURL}${USER_MANAGEMENT_AUTH_SIGN_IN_GOOGLE}`)}
                      className="w-full h-12 rounded-full bg-gray-100 text-gray-700 flex items-center justify-center gap-3 hover:bg-gray-200 transition"
                  >
                      {SignInLanguage.google}
                  </Button>
                  <Button
                      icon={<img src={require('../../../resources/media/social/linkedin.png')} width={24}/>}
                      block
                      // onClick={() => window.location.replace(`${baseURL}${USER_MANAGEMENT_AUTH_SIGN_IN_LINKEDIN}`)}
                      className="w-full h-12 rounded-full bg-gray-100 text-gray-700 flex items-center justify-center gap-3 hover:bg-gray-200 transition"
                  >
                      {SignInLanguage.linkedin}
                  </Button>
                  <Space direction="vertical" size={5} style={{width: '100%'}}>
                  <Space className="ml-3" size={5}><Typography.Text className={'text-xs'}>{SignUpLanguage.signUpDescription}</Typography.Text><Link className={'font-bold text-xs'} to={'/sign-up'}>{SignUpLanguage.signUp}</Link></Space>
                  <Space className="ml-3" size={5}><Typography.Text className={'text-xs'}>{SignInLanguage.resetPasswordDescription}</Typography.Text><Link className={'font-bold text-xs'} to={'/reset-password'}>{SignInLanguage.resetPassword}</Link></Space>
                  </Space>
              </Space>
          </Form>
        </>
    )
}
