import React, { useContext, useEffect, useState } from "react";
import {Input, Button, Form, App, Space, Typography} from "antd";
import { Helmet } from 'react-helmet-async';
import {Link, useNavigate, useParams} from "react-router-dom";
import { Regex, API, Enum } from "../../../resources/constants";
import language from "../../../resources/languages/en_US";

// Interfaces
import { AxiosError } from "../../../interfaces/axios"

// Contexts
import GlobalContext from "../../../contexts/global";
import AxiosContext from "../../../contexts/axios";

const { Pages: { ResetPassword: ResetPasswordLanguage, SignIn: SignInLanguage }, Validation, Message: MessageLanguage } = language
const { isNumber, isEmail } = Regex
const { USER_MANAGEMENT_AUTH_REQUEST_RESET_PASSWORD, USER_MANAGEMENT_AUTH_RESET_PASSWORD } = API
const { Message } = Enum

export default function ResetPassword() {

    const [form] = Form.useForm()
    const [, forceUpdate] = useState({})
    const { token } = useParams()
    const { meta, baseURL, dispatch } = useContext(GlobalContext)
    const { axios } = useContext(AxiosContext)
    const navigate = useNavigate()
    const { message } = App.useApp()

    useEffect(() => {
        // To disable submit button at the beginning.
        forceUpdate({});
    }, []);

  const onFinish = ({ email, password }: { email: string, password: string }) => {
    if (token) {
      axios.patch(USER_MANAGEMENT_AUTH_RESET_PASSWORD, { password, token }).then((response: {}) => {
        message.success(MessageLanguage[Message.CHANGE_PASSWORD]).then(response => response)
        navigate('/sign-in')
      }, async (error: AxiosError) => {
        const { response: { data } } = error;
        // @ts-ignore
        message.error(MessageLanguage[data.message]).then(response => response )
      })
    } else {
      axios.post(USER_MANAGEMENT_AUTH_REQUEST_RESET_PASSWORD, { email }).then((response: {}) => {
        message.success(MessageLanguage[Message.RESET_PASSWORD_LINK]).then(response => response)
        form.resetFields()
      }, async (error: AxiosError) => {
        const { response: { data } } = error;
        // @ts-ignore
        message.error(MessageLanguage[data.message]).then(response => response )
      })
    }
  };

    return (
        <>
          { meta?.title && (
            <Helmet>
              <title>{ (token ? ResetPasswordLanguage.changePassword : ResetPasswordLanguage.resetPassword) + ' - ' + meta.title }</title>
            </Helmet>
          )
          }
          <Form form={form} name="reset-password" className={'sign-in reset-password w-full max-w-md bg-white rounded-3xl shadow-2xl p-10'} autoComplete="off" onFinish={onFinish}>
              <Space direction="vertical" size="middle" style={{width: '100%'}}>
                  <div className="flex justify-center">
                      <img alt={token ? ResetPasswordLanguage.changePassword : ResetPasswordLanguage.resetPassword} src={require('../../../resources/media/logo.png')} width={70}/>
                  </div>
                  <Space direction="vertical" size={3} style={{width: '100%'}}>
                      <Typography.Title
                          className="text-center"
                          level={2}
                      >{token ? ResetPasswordLanguage.changePassword : ResetPasswordLanguage.resetPassword}</Typography.Title>
                      {
                          !token && (
                              <Typography.Title
                                  className="text-center"
                                  level={3}
                              >{ ResetPasswordLanguage.description }</Typography.Title>
                          )
                      }
                  </Space>
                  {
                      token ? (
                          <>
                              <Form.Item
                                  label={ResetPasswordLanguage.password}
                                  className="mb-2"
                                  name="password"
                                  hasFeedback
                                  rules={[
                                      {required: true, message: `${ResetPasswordLanguage.password} ${Validation.required}`},
                                  ]}
                              >
                                  <Input.Password
                                      className="w-full h-12 rounded-full border border-gray-300 px-5 text-sm focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent transition"
                                      placeholder={ResetPasswordLanguage.passwordPlaceholder}
                                  />
                              </Form.Item>
                              <Form.Item
                                  label={ResetPasswordLanguage.confirm}
                                  className="mb-2"
                                  name="confirm"
                                  hasFeedback
                                  dependencies={['password']}
                                  rules={[
                                      {
                                          required: true,
                                          message: `${ResetPasswordLanguage.confirm} ${Validation.required}`
                                      },
                                      ({getFieldValue}) => ({
                                          validator(_, value) {
                                              if (!value || getFieldValue('password') === value) {
                                                  return Promise.resolve();
                                              }
                                              return Promise.reject(new Error(Validation.newPasswordConfirm));
                                          },
                                      }),
                                  ]}
                              >
                                  <Input.Password
                                      className="w-full h-12 rounded-full border border-gray-300 px-5 text-sm focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent transition"
                                      placeholder={ResetPasswordLanguage.confirm}
                                  />
                              </Form.Item>
                          </>
                      ) : (
                          <Form.Item
                              label={ResetPasswordLanguage.email}
                              className="mb-2"
                              name="email"
                              hasFeedback
                              rules={[
                                  {required: true, message: `${ResetPasswordLanguage.email} ${Validation.required}`},
                                  {pattern: isEmail, message: Validation.email},
                              ]}
                          >
                              <Input
                                  className="w-full h-12 rounded-full border border-gray-300 px-5 text-sm focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent transition"
                                  placeholder={ResetPasswordLanguage.emailPlaceholder}
                              />
                          </Form.Item>
                      )
                  }
                  <Form.Item className="mb-2" shouldUpdate>
                      {() => (
                          <Button
                              type="primary"
                              block
                              htmlType="submit"
                              className="w-full h-12 rounded-full bg-gradient-to-r from-gray-800 to-black text-white font-medium hover:opacity-90 transition duration-200"
                          >
                              {token ? ResetPasswordLanguage.changePassword : ResetPasswordLanguage.sendResetLink}
                          </Button>
                      )}
                  </Form.Item>
                  <Space direction="vertical" size={5} style={{width: '100%'}}>
                      <Space className="ml-3" size={5}><Typography.Text className={'text-xs'}>{ResetPasswordLanguage.signInDescription}</Typography.Text><Link className={'font-bold text-xs'} to={'/sign-in'}>{ResetPasswordLanguage.signIn}</Link></Space>
                  </Space>
              </Space>
          </Form>
        </>
    )
}
