import React, {useContext, useEffect, useState} from 'react'
import {Typography, Splitter, Row, Col, Space, Avatar, Form, App, Input, Select, Checkbox, Button} from 'antd'
import ReactQuill from 'react-quill'
import { FaAvianex, FaArchway, FaArtstation, FaAnchor, FaAddressBook, FaArchive, FaRegQuestionCircle } from "react-icons/fa"
import {Link, useNavigate} from "react-router-dom";
import { Helmet } from 'react-helmet-async';
import { Regex, ActionType, API, Enum } from "../../resources/constants";
import language from "../../resources/languages/en_US"

// Interfaces
import { AxiosError } from "../../interfaces/axios"
import { Welcome as WelcomeType } from "../../interfaces/pages/welcome/welcome"

// Contexts
import GlobalContext from "../../contexts/global";
import AxiosContext from "../../contexts/axios";

const { Pages: { Welcome: WelcomeLanguage }, Validation, Message: MessageLanguage, Share } = language
const { WELCOME_WELCOME } = API

export default function Welcome() {

    const [form] = Form.useForm()
    const [, forceUpdate] = useState({})
    const { user, meta } = useContext(GlobalContext)
    const { axios } = useContext(AxiosContext)
    const navigate = useNavigate()
    const { message } = App.useApp()

    useEffect(() => {
        // To disable submit button at the beginning.
        forceUpdate({});
    }, []);

    const onFinish = (welcome: WelcomeType) => {
        axios.post(WELCOME_WELCOME, welcome).then((response: { data: {}}) => {
            navigate("/");
        }, async (error: AxiosError) => {
            const { response: { data } } = error;
            // @ts-ignore
            message.error(MessageLanguage[data.message]).then(response => response )
        })
    };

    return (
      <>
          <Helmet>
              <title>{ WelcomeLanguage.title + ' - ' + meta?.title }</title>
          </Helmet>
          <div className={'welcome'}>
              <Row gutter={20}>
                  <Col span={6}>
                      <div className="h-full rounded-2xl bg-white p-4 shadow-md">
                          <Space direction="vertical" size={25} style={{width: '100%'}}>
                              <Typography.Title level={1}>{WelcomeLanguage.whyFelixFusion}</Typography.Title>
                              <Space direction="vertical" size={10} style={{width: '100%'}}>
                                  <Space size={10}><Avatar size={45} icon={<FaAvianex size={17}/>}/><Typography.Text
                                      className={'text-xs font-bold'}>{WelcomeLanguage.federalStateLocal}</Typography.Text></Space>
                                  <Space size={10}><Avatar size={45} icon={<FaArchway size={17}/>}/><Typography.Text
                                      className={'text-xs font-bold'}>{WelcomeLanguage.opportunities300000}</Typography.Text></Space>
                                  <Space size={10}><Avatar size={45} icon={<FaArtstation size={17}/>}/><Typography.Text
                                      className={'text-xs font-bold'}>{WelcomeLanguage.proposalsHours}</Typography.Text></Space>
                                  <Space size={10}><Avatar size={45} icon={<FaAnchor size={17}/>}/><Typography.Text
                                      className={'text-xs font-bold'}>{WelcomeLanguage.teammateCollaboration}</Typography.Text></Space>
                                  <Space size={10}><Avatar size={45} icon={<FaAddressBook size={17}/>}/><Typography.Text
                                      className={'text-xs font-bold'}>{WelcomeLanguage.highGradeSecurity}</Typography.Text></Space>
                                  <Space size={10}><Avatar size={45} icon={<FaArchive size={17}/>}/><Typography.Text
                                      className={'text-xs font-bold'}>{WelcomeLanguage.allOneWorkflow}</Typography.Text></Space>
                              </Space>
                              <Typography.Title level={1}>{WelcomeLanguage.TrustedPublicSector}</Typography.Title>
                              <img alt={WelcomeLanguage.TrustedPublicSector} src={require('../../resources/media/trusted.png')} width={250}/>
                          </Space>
                      </div>
                  </Col>
                  <Col span={18}>
                  <div className="h-full rounded-2xl bg-white p-6 shadow-md">
                      <Space direction="vertical" size={25} style={{width: '100%'}}>
                          <img alt={WelcomeLanguage.welcomeFelixFusion}
                               src={require('../../resources/media/logo.png')} width={50}/>
                          <Typography.Title level={1}>{WelcomeLanguage.welcomeFelixFusion}</Typography.Title>
                          <Typography.Text className={'text-gray-400 text-xs'}>{WelcomeLanguage.letGetYouOnboarded}</Typography.Text>
                          <Form layout="vertical" form={form} name="welcome" className={'welcome'} autoComplete="off" onFinish={onFinish}>
                              <Form.Item
                                  label={<Space><Typography.Text>{WelcomeLanguage.companyName}</Typography.Text><FaRegQuestionCircle /></Space>}
                                  name="companyName"
                                  hasFeedback
                                  rules={[
                                      {required: true, message: `${WelcomeLanguage.companyName} ${Validation.required}`},
                                  ]}
                              >
                                  <Input
                                      className="peer w-full h-12 rounded-full bg-white border border-gray-300 px-5 text-sm placeholder-transparent focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent transition"
                                      minLength={3}
                                      placeholder={WelcomeLanguage.companyNamePlaceholder}
                                  />
                              </Form.Item>
                              <Form.Item
                                  label={<Space><Typography.Text>{WelcomeLanguage.companyWebsite}</Typography.Text><FaRegQuestionCircle /></Space>}
                                  name="companyWebsite"
                                  hasFeedback
                                  rules={[
                                      {required: true, message: `${WelcomeLanguage.companyWebsite} ${Validation.required}`},
                                  ]}
                              >
                                  <Input
                                      className="peer w-full h-12 rounded-full bg-white border border-gray-300 px-5 text-sm placeholder-transparent focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent transition"
                                      minLength={3}
                                      placeholder={WelcomeLanguage.companyWebsitePlaceholder}
                                  />
                              </Form.Item>
                              <Form.Item
                                  label={<Space><Typography.Text>{WelcomeLanguage.companyDescription}</Typography.Text><FaRegQuestionCircle /></Space>}
                                  name="companyDescription"
                                  rules={[]}
                              >
                                  <ReactQuill
                                      modules={{
                                          toolbar: [
                                              ['bold', 'italic', 'underline'],
                                              [{ 'list': 'ordered' }, { 'list': 'bullet' }],
                                          ],
                                      }}
                                      formats={ [
                                          'bold', 'italic', 'underline',
                                          'list', 'bullet'
                                      ]}
                                      theme="snow"
                                  />
                              </Form.Item>
                              <Form.Item
                                  label={<Space><Typography.Text>{WelcomeLanguage.targetOpportunityType}</Typography.Text><FaRegQuestionCircle /></Space>}
                                  name="targetOpportunityType"
                                  hasFeedback
                                  rules={[]}
                              >
                                  <Select
                                      showSearch
                                      allowClear
                                      size={'large'}
                                      optionFilterProp="label"
                                      placeholder={Share.pleaseSelect}
                                      options={[]}
                                  />
                              </Form.Item>
                              <Form.Item
                                  name="acceptTermsService"
                                  rules={[]}
                              >
                                  <Checkbox>
                                      {WelcomeLanguage.acceptTermsService}
                                  </Checkbox>
                              </Form.Item>
                          </Form>
                          <Form.Item shouldUpdate>
                              {() => (
                                  <Button
                                      type="primary"
                                      htmlType="submit"
                                      className="float-right h-10 rounded-full bg-gradient-to-r from-gray-800 to-black text-white font-medium hover:opacity-90 transition duration-200"
                                  >
                                      {Share.submit}
                                  </Button>
                              )}
                          </Form.Item>
                      </Space>
                  </div>
                  </Col>
              </Row>
          </div>
      </>
    )
}
