import React, { useContext } from 'react'
import { Link } from "react-router-dom"
import { useLocation } from "react-router-dom"
import _ from 'lodash'
import { Menu, Space } from 'antd'
import { getRoutes } from "./route";

// Contexts
import GlobalContext from '../../contexts/global'

export default function Index({ collapsed = false, setCollapsed }: { collapsed?: boolean, setCollapsed?: (collapsed: boolean) => void }) {

    const { user } = useContext(GlobalContext)
    const location = useLocation()
    const items = getRoutes(user).filter((item: any) => item?.menu).map((item: any) => ({
        key: item.key,
        icon: <Space className={'menu-item'} direction="vertical" size={3} style={{width: '100%'}}>{item.icon}<span>{item.label}</span></Space>,
        label: <Link to={item.key}>{item.label}</Link>,
        children: !_.isEmpty(item.children) ?? item.children,
    }))

    return (
        <Menu
            theme="light"
            mode="inline"
            defaultSelectedKeys={['/']}
            defaultOpenKeys={[`/${location.pathname.split('/')[1]}`]}
            selectedKeys={[location.pathname]}
            onSelect={() => setCollapsed && setCollapsed(!collapsed)}
            items={items}
        />
    )
}
