import React, { ReactElement } from 'react'
import { FaHome, FaRegComments, FaSearch, FaBookOpen, FaLayerGroup } from "react-icons/fa";
import language from "../../resources/languages/en_US";

// Interfaces
import { Route } from "../../interfaces/layouts/dashboard";

const { Layouts: { Dashboard: { Route: RouteLanguage } } } = language

export const getRoutes = (user: any) => {

  let routes: Route[] = [
    {
      key: '/',
      icon: <FaHome />,
      label: RouteLanguage.home,
      menu: true,
      children: [],
    },
  ];

  routes.push( {
    key: '/search',
    icon: <FaSearch />,
    label: RouteLanguage.search,
    menu: true,
    children: [],
  });

  routes.push( {
    key: '/ask-ai',
    icon: <FaRegComments />,
    label: RouteLanguage.askAI,
    menu: true,
    children: [],
  });

  routes.push( {
    key: '/pursuits',
    icon: <FaLayerGroup />,
    label: RouteLanguage.pursuits,
    menu: true,
    children: [],
  });

  routes.push( {
    key: '/library',
    icon: <FaBookOpen />,
    label: RouteLanguage.library,
    menu: true,
    children: [],
  });

  return routes;
}
