import React, { useState, useContext, ReactElement } from 'react'
import { useNavigate, useLocation, Link } from "react-router-dom"
import _ from "lodash";
import { isMobileOnly, isDesktop } from "react-device-detect"
import { FaChevronRight } from "react-icons/fa"
import { Layout, Button, theme, App, Space, Affix, Breadcrumb } from 'antd'
import { getRoutes } from "./route";
import language from "../../resources/languages/en_US";
import { ActionType, Enum, API } from "../../resources/constants";

// Interfaces
import { AxiosError } from "../../interfaces/axios";
import { Route } from "../../interfaces/layouts/dashboard";

// Contexts
import GlobalContext from '../../contexts/global'
import AxiosContext from '../../contexts/axios'

const { Header } = Layout
const { Message: MessageLanguage, Layouts: { Dashboard: { Header: HeaderLanguage } } } = language
const { Message } = Enum

export default function Index({ collapsed, setCollapsed }: { collapsed: boolean, setCollapsed: (collapsed: boolean) => void }) {

  const { token: { colorBgContainer } } = theme.useToken()
  const { user, baseURL, accessToken, dispatch } = useContext(GlobalContext)
  const { axios } = useContext(AxiosContext)
  const { pathname } = useLocation()
  const splitPathname= pathname.split("/").filter(item => item).map(item => '/' + item)
  if (_.isEmpty(splitPathname)) splitPathname.push('/')
  const { message } = App.useApp()
  const items= getRoutes(user)

  const flattenItems = (items: Route[], flatten: Route[]) => {
    for (const item of items)
      if (!_.isEmpty(item.children))
        flattenItems(item.children, flatten)
    flatten.push(...items)
  }

  const breadcrumb = () => {
    const breadcrumbs: ReactElement[] = [<Breadcrumb.Item key='company'>{user?.company || HeaderLanguage.yourCompany}</Breadcrumb.Item>]
    const flatten: Route[] = []
    flattenItems(items, flatten)
    for (let i = 0; i < splitPathname.length; i++) {
      for (let j = 0; j <= i; j++) {
        if (j === i) {
          const item = _.findLast(flatten, { key: splitPathname.slice(0, j + 1).join() });
          if (item?.key) breadcrumbs.push(<Breadcrumb.Item key={item.key}><Link to={item.key}>{item?.label}</Link></Breadcrumb.Item>)
        }
      }
    }

    return (
      <Breadcrumb separator={<FaChevronRight size={12}/>} className={'ml-8 mt-6'}>
        {breadcrumbs}
      </Breadcrumb>
    )
  }

    return (
        <Header style={{background: colorBgContainer}}>
          {
            breadcrumb()
          }
        </Header>
    )
}
