import React, { useState, useContext } from 'react'
import { Layout, Drawer, Affix, Flex, Space, Avatar, App } from 'antd'
import { useNavigate } from "react-router-dom";
import Cookies from "js-cookie";
import { isMobileOnly, isDesktop } from "react-device-detect"
import { FaTimes, FaRegUser, FaCog, FaSignOutAlt } from "react-icons/fa"
import language from "../../resources/languages/en_US";
import { ActionType, Enum, API } from "../../resources/constants";

// Components
import Content from './content'
import Footer from './footer'
import Header from './header'
import Menu from './menu'

// Interfaces
import { AxiosError } from "../../interfaces/axios";

// Contexts
import GlobalContext from '../../contexts/global'
import AxiosContext from '../../contexts/axios'

const { Layouts: { Dashboard: { Menu: MenuLanguage } },  Message: MessageLanguage, } = language
const { Sider } = Layout
const { SET_USER, SET_ACCESS_TOKEN } = ActionType
const { Message } = Enum
const { USER_MANAGEMENT_AUTH_SIGN_OUT, FILE_MANAGEMENT_FILE_DOWNLOAD } = API

export default function Index() {

    const [collapsed, setCollapsed] = useState(true)
    const { user, baseURL, accessToken, dispatch } = useContext(GlobalContext)
    const { axios } = useContext(AxiosContext)
    const navigate = useNavigate()
    const { message } = App.useApp()

    const signOut = () => {
        axios.get(USER_MANAGEMENT_AUTH_SIGN_OUT).then((response: {}) => {
            Cookies.remove('accessToken')
            dispatch({ type: SET_ACCESS_TOKEN , payload: { accessToken: null }})
            dispatch({ type: SET_USER , payload: { user: null }})
            message.success(MessageLanguage[Message.SIGN_OUT_PROFILE]).then(response => response)
            navigate("/")
        }).catch((error: AxiosError) => {
            const { response: { data } } = error;
            // @ts-ignore
            message.error(data.message).then(response => response )
        })
    }

    return (
        <Layout className='dashboard-layout'>
            {
                user ? (
                    <>
                        <Sider
                            theme="light"
                            trigger={null}
                            collapsible
                            collapsed={collapsed}
                            width={250}
                        >
                            <Affix>
                                <Flex vertical={true} justify={'space-between'} style={{minHeight: '100vh'}}>
                                    <Space direction="vertical" size={5}>
                                        <div className={"menu-logo"}/>
                                        <Menu/>
                                    </Space>
                                    <Space direction="vertical" size={10} className={'mx-auto mb-4'}>
                                        <Avatar size={45} icon={<FaSignOutAlt size={17} />} onClick={signOut} />
                                        <Avatar size={45} onClick={() => navigate("/profile")} icon={user?.avatar ? <img src={baseURL + FILE_MANAGEMENT_FILE_DOWNLOAD + user.avatar + `?width=45&height=45&token=${accessToken}`} width={45} /> : <FaRegUser size={17} />} />
                                    </Space>
                                </Flex>
                            </Affix>
                        </Sider>
                        <Layout>
                            <Header collapsed={collapsed} setCollapsed={setCollapsed} />
                            <Content />
                            <Footer />
                        </Layout>
                    </>
                ) : (
                    <>
                        <Content />
                        <Footer />
                    </>
                )
            }
        </Layout>
    )
}
