import React, { useReducer, useEffect } from "react";
import Cookies from "js-cookie";
import axios2 from "axios";
import { BrowserRouter , Route , Routes } from "react-router-dom";
import { ConfigProvider, App as AppAntd } from "antd";
import { Helmet } from 'react-helmet-async';
import dayjs, {Dayjs} from 'dayjs'
import utc from 'dayjs/plugin/utc';
import timezone from 'dayjs/plugin/timezone';
import language from "./resources/languages/en_US";
import { AntDesign, ActionType, API, Enum } from "./resources/constants";

// Commons
import PendingRequest from './commons/pending-request'
import AuthRoute from './commons/auth-route'
import NoAuthRoute from './commons/no-auth-route'

// Interfaces
import { AxiosError } from "./interfaces/axios"
import { InternalAxiosRequestConfig, AxiosResponse } from "axios";

// Reducers
import GlobalReducer from './reducers/global'
import AxiosReducer from './reducers/axios'

// Contexts
import GlobalContext from './contexts/global'
import AxiosContext from './contexts/axios'

// Pages
import SignIn from "./pages/user-management/auth/sign-in"
import SignUp from "./pages/user-management/auth/sign-up"
import ResetPassword from "./pages/user-management/auth/reset-password"
import NotFound from "./pages/not-found"
import Forbidden from "./pages/forbidden"
import Home from "./pages/home/home"
import Welcome from "./pages/welcome/welcome"

// Layouts
import DashboardLayout from "./layouts/dashboard"

dayjs.extend(utc);
dayjs.extend(timezone);
const { SET_PENDING_REQUESTS, SET_USER, SET_ACCESS_TOKEN } = ActionType
const { USER_MANAGEMENT_PROFILE_MY_ACCOUNT } = API;
const { App: AppLanguage } = language;

export default function App() {

    const { protocol, hostname, port } = window.location;
    const host = port ? `${hostname}:${port}` : hostname;

    const [{
        user,
        meta,
        url,
        baseURL,
        accessToken,
    }, dispatchGlobal] = useReducer(GlobalReducer , {
        user: null,
        meta: {
            title: AppLanguage.title,
            description: AppLanguage.description,
        },
        accessToken: Cookies.get("accessToken"),
        url: `${protocol}//${host}/`,
        baseURL: `${protocol}//${host}/`,
    })

    const [{
        pendingRequests,
        axios,
    }, dispatchAxios] = useReducer(AxiosReducer , {
        pendingRequests: 0,
        axios: axios2.create({
            baseURL,
            timeout: Number(process.env.REACT_APP_TIME_OUT),
            withCredentials: true,
        })
    })

    const pendingRequest = (counter: number) => {
        const element = document.getElementById('pending-request')
        if (element) element.style.display = counter ? "flex" : "none";
    }

    useEffect(() => {
        let counter = 0;
        // All api request
        axios.interceptors.request.use(
            (config: InternalAxiosRequestConfig) => {
                //dispatchAxios({ type: SET_PENDING_REQUESTS , payload: { plus: true }})
                pendingRequest(++counter)
                const accessToken = Cookies.get("accessToken")
                config.headers.Authorization = accessToken && `Bearer ${accessToken}`
                return config
            },
            (error: any) => Promise.reject(error)
        );
        // All api response
        axios.interceptors.response.use(
            (response: AxiosResponse ) => {
                //dispatchAxios({ type: SET_PENDING_REQUESTS , payload: { plus: false }})
                pendingRequest(--counter)
                return response
            },
            (error: AxiosError) => {
                const { response: { status } } = error
                if (status === 401) {
                    Cookies.remove('accessToken')
                    dispatchGlobal({ type: SET_ACCESS_TOKEN , payload: { accessToken: null }})
                    dispatchGlobal({ type: SET_USER , payload: { user: null }})
                }

                //dispatchAxios({ type: SET_PENDING_REQUESTS , payload: { plus: false }})
                pendingRequest(--counter)
                return Promise.reject(error)
            }
        );
        axios.get(USER_MANAGEMENT_PROFILE_MY_ACCOUNT).then((response: { data: {} }) => {
            const { data: user } = response
            dispatchGlobal({ type: SET_USER , payload: { user }})
        }).catch( (error: {}) => error );
    }, [])

    return (
        <ConfigProvider
            direction={"ltr"}
            locale={language}
            theme={AntDesign.theme}
        >
            <AppAntd>
                <PendingRequest pendingRequests={pendingRequests} />
                <Helmet>
                    { meta?.title && <title>{meta.title}</title> }
                    { meta?.description && <meta name="description" content={meta.description} /> }
                </Helmet>
                <GlobalContext.Provider value={{
                    user,
                    meta,
                    url,
                baseURL,
                accessToken,
                dispatch: dispatchGlobal
            }}>
                <AxiosContext.Provider value={{
                    pendingRequests,
                    axios,
                    dispatch: dispatchAxios
                }}>
                    <BrowserRouter basename={process.env.REACT_APP_BASE_NAME}>
                        <Routes>
                            <Route path="/" element={<DashboardLayout />}>
                                <Route index element={<AuthRoute><Home /></AuthRoute>} />
                                <Route path="sign-in" element={<NoAuthRoute><SignIn /></NoAuthRoute>} />
                                <Route path="sign-up" element={<NoAuthRoute><SignUp /></NoAuthRoute>} />
                                <Route path="reset-password" element={<NoAuthRoute><ResetPassword /></NoAuthRoute>} >
                                    <Route path=":token" />
                                 </Route>
                                <Route path="welcome" element={<AuthRoute><Welcome /></AuthRoute>} />
                                <Route path="forbidden" element={<AuthRoute><Forbidden /></AuthRoute>} />
                                <Route path="*" element={<NotFound />} />
                            </Route>
                        </Routes>
                    </BrowserRouter>
                </AxiosContext.Provider>
            </GlobalContext.Provider>
            </AppAntd>
        </ConfigProvider>
    )
}
