import React, { useContext } from 'react'
import { Link } from "react-router-dom"
import { Result } from 'antd'
import { Helmet } from 'react-helmet-async'
import language from "../resources/languages/en_US"

// Contexts
import GlobalContext from "../contexts/global";

const { Pages: { NotFound: NotFoundLanguage }, Share } = language

export default function Index() {

    const { user, meta } = useContext(GlobalContext)

    return (
        <>
            <Helmet>
                <title>{NotFoundLanguage.title + ' - ' + meta?.title }</title>
            </Helmet>
            <Result
                className={'not-found'}
                status="404"
                title="404"
                subTitle={NotFoundLanguage.description}
                extra={<Link to="/">{Share.backHome}</Link>}
            />
        </>
    )
}
