import React, { useContext, useEffect, useState } from "react";
import Cookies from "js-cookie";
import { Helmet } from 'react-helmet-async';
import {Input, Button, Form, App, Space, Typography} from "antd";
import {Link, useNavigate} from "react-router-dom";
import { Regex, ActionType, API, Enum } from "../../../resources/constants";
import language from "../../../resources/languages/en_US";

// Interfaces
import { AxiosError } from "../../../interfaces/axios"

// Contexts
import GlobalContext from "../../../contexts/global";
import AxiosContext from "../../../contexts/axios";

const { Pages: { SignUp: SignUpLanguage, SignIn: SignInLanguage }, Validation, Message: MessageLanguage, Share } = language
const { isEmail } = Regex
const { SET_USER, SET_ACCESS_TOKEN } = ActionType
const { USER_MANAGEMENT_AUTH_SIGN_UP, USER_MANAGEMENT_PROFILE_MY_ACCOUNT, USER_MANAGEMENT_AUTH_SIGN_IN_GOOGLE } = API
const { Message } = Enum

export default function SignUp() {

    const [form] = Form.useForm()
    const [, forceUpdate] = useState({})
    const { meta, baseURL, dispatch } = useContext(GlobalContext)
    const { axios } = useContext(AxiosContext)
    const navigate = useNavigate()
    const { message } = App.useApp()

    useEffect(() => {
        // To disable submit button at the beginning.
        forceUpdate({});
    }, []);

    const onFinish = ({ firstName, lastName, email, password }: { firstName: string, lastName: string, email: string, password: string }) => {
        axios.post(USER_MANAGEMENT_AUTH_SIGN_UP, { firstName, lastName, email, password }).then((response: { data: { accessToken: string }}) => {
            const { data: { accessToken } } = response
            Cookies.set('accessToken', accessToken, { expires: 365 })
            dispatch({ type: SET_ACCESS_TOKEN , payload: { accessToken }})
            axios.get(USER_MANAGEMENT_PROFILE_MY_ACCOUNT).then((response: { data: {} }) => {
                const { data: user } = response
                dispatch({ type: SET_USER , payload: { user }})
                navigate("/welcome");
                message.success(MessageLanguage[Message.SIGN_IN_PROFILE]).then(response => response)
            })
        }, async (error: AxiosError) => {
            const { response: { data } } = error;
            // @ts-ignore
            message.error(MessageLanguage[data.message]).then(response => response )
        })
    };

    return (
        <>
          { meta?.title && (
            <Helmet>
              <title>{ SignUpLanguage.signUp + ' - ' + meta.title }</title>
            </Helmet>
          )
          }
          <Form form={form} name="sign-up" className={'sign-in sign-up w-full max-w-md bg-white rounded-3xl shadow-2xl p-10'} autoComplete="off" onFinish={onFinish}>
              <Space direction="vertical" size="middle" style={{width: '100%'}}>
                  <div className="flex justify-center">
                      <img alt={SignUpLanguage.signUp} src={require('../../../resources/media/logo.png')} width={70}/>
                  </div>
                  <Typography.Title
                      className="text-center"
                      level={2}
                  >{SignUpLanguage.title}</Typography.Title>
                  <Form.Item
                      label={SignUpLanguage.firstName}
                      className="mb-2"
                      name="firstName"
                      hasFeedback
                      rules={[
                          {required: true, message: `${SignUpLanguage.firstName} ${Validation.required}`},
                          {min: 3, message: `${SignUpLanguage.firstName} ${Validation.min} 3 ${Validation.length}`},
                          {max: 30, message: `${SignUpLanguage.firstName} ${Validation.max} 30 ${Validation.length}`},
                      ]}
                  >
                      <Input
                          className="peer w-full h-12 rounded-full bg-white border border-gray-300 px-5 text-sm placeholder-transparent focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent transition"
                          minLength={3}
                          placeholder={SignUpLanguage.firstNamePlaceholder}
                      />
                  </Form.Item>
                  <Form.Item
                      label={SignUpLanguage.lastName}
                      className="mb-2"
                      name="lastName"
                      hasFeedback
                      rules={[
                          {required: true, message: `${SignUpLanguage.lastName} ${Validation.required}`},
                          {min: 3, message: `${SignUpLanguage.lastName} ${Validation.min} 3 ${Validation.length}`},
                          {max: 30, message: `${SignUpLanguage.lastName} ${Validation.max} 30 ${Validation.length}`},
                      ]}
                  >
                      <Input
                          className="peer w-full h-12 rounded-full bg-white border border-gray-300 px-5 text-sm placeholder-transparent focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent transition"
                          minLength={3}
                          placeholder={SignUpLanguage.lastNamePlaceholder}
                      />
                  </Form.Item>
                  <Form.Item
                      label={SignUpLanguage.email}
                      className="mb-2"
                      name="email"
                      hasFeedback
                      rules={[
                          {required: true, message: `${SignUpLanguage.email} ${Validation.required}`},
                          {pattern: isEmail, message: Validation.email},
                      ]}
                  >
                      <Input
                          className="peer w-full h-12 rounded-full bg-white border border-gray-300 px-5 text-sm placeholder-transparent focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent transition"
                          placeholder={SignUpLanguage.emailPlaceholder}
                      />
                  </Form.Item>
                  <Form.Item
                      label={SignUpLanguage.password}
                      className="mb-2"
                      name="password"
                      hasFeedback
                      rules={[
                          {required: true, message: `${SignUpLanguage.password} ${Validation.required}`},
                      ]}
                  >
                      <Input.Password
                          className="w-full h-12 rounded-full border border-gray-300 px-5 text-sm focus:outline-none focus:ring-2 focus:ring-black focus:border-transparent transition"
                          placeholder={SignUpLanguage.passwordPlaceholder}
                      />
                  </Form.Item>
                  <Form.Item className="mb-2" shouldUpdate>
                      {() => (
                          <Button
                              type="primary"
                              block
                              htmlType="submit"
                              className="w-full h-12 rounded-full bg-gradient-to-r from-gray-800 to-black text-white font-medium hover:opacity-90 transition duration-200"
                          >
                              {SignUpLanguage.signUp}
                          </Button>
                      )}
                  </Form.Item>
                  <Typography.Text className="flex justify-center">{Share.or}</Typography.Text>
                  <Button
                      icon={<img src={require('../../../resources/media/social/google.png')} width={24}/>}
                      block
                      // onClick={() => window.location.replace(`${baseURL}${USER_MANAGEMENT_AUTH_SIGN_IN_GOOGLE}`)}
                      className="w-full h-12 rounded-full bg-gray-100 text-gray-700 flex items-center justify-center gap-3 hover:bg-gray-200 transition"
                  >
                      {SignUpLanguage.google}
                  </Button>
                  <Button
                      icon={<img src={require('../../../resources/media/social/linkedin.png')} width={24}/>}
                      block
                      // onClick={() => window.location.replace(`${baseURL}${USER_MANAGEMENT_AUTH_SIGN_IN_LINKEDIN}`)}
                      className="w-full h-12 rounded-full bg-gray-100 text-gray-700 flex items-center justify-center gap-3 hover:bg-gray-200 transition"
                  >
                      {SignUpLanguage.linkedin}
                  </Button>
                  <Space direction="vertical" size={5} style={{width: '100%'}}>
                      <Space className="ml-3" size={5}><Typography.Text className={'text-xs'}>{SignInLanguage.signInDescription}</Typography.Text><Link className={'font-bold text-xs'} to={'/sign-in'}>{SignInLanguage.signIn}</Link></Space>
                  </Space>
              </Space>
          </Form>
        </>
    )
}
